import random, collections, itertools, math, time

def girth_edges(n, edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    g=10**9
    for s in range(n):
        dist=[-1]*n; par=[-1]*n
        q=collections.deque([s]); dist[s]=0
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g, dist[u]+dist[v]+1)
    return None if g==10**9 else g

def can_add(n, adj, u,v):
    if v in adj[u]: return False
    # distance from u to v in current graph; adding creates cycle dist+1. need dist>=7 or no path
    dist=[-1]*n; q=collections.deque([u]); dist[u]=0
    while q:
        x=q.popleft()
        if dist[x]>=6: continue
        for y in adj[x]:
            if dist[y]<0:
                dist[y]=dist[x]+1
                if y==v: return False # dist <=6
                q.append(y)
    return True

def random_greedy(n=21, parts=(10,11), attempts=10000):
    A=list(range(parts[0])); B=list(range(parts[0],n))
    candidates=[(a,b) for a in A for b in B]
    best=[]
    for t in range(attempts):
        adj=[set() for _ in range(n)]; edges=[]
        cand=candidates[:]
        random.shuffle(cand)
        # maybe random process repeatedly choose valid
        while True:
            valid=[e for e in cand if can_add(n,adj,*e)]
            if not valid: break
            # choose maybe prioritize degree balance
            if random.random()<0.7:
                # random among top by degree score low degrees
                scored=[]
                for u,v in valid:
                    scored.append((len(adj[u])+len(adj[v])+random.random()*2,u,v))
                scored.sort()
                _,u,v=random.choice(scored[:max(1,len(scored)//3)])
            else:
                u,v=random.choice(valid)
            adj[u].add(v); adj[v].add(u); edges.append((u,v));
            cand.remove((u,v))
            if len(edges)>=27:
                print('found', t, len(edges), girth_edges(n,edges)); return edges
        if len(edges)>len(best):
            best=edges[:]
            print('best', len(best), 't',t, 'g', girth_edges(n,best))
    return best

edges=random_greedy(attempts=20000)
